const itens = [
  { doc: '1IywT4jszZAVuBCBk3p_8DgsUeffoTCkkiBojdQOybZk', aba: 'Clientes', criar: false,
    cabecalhos: ['Link do Relatório', 'Enviar Relatório', 'Relatório - Melhorias', 'Relatório - Ajustes'] },
  { doc: '1IywT4jszZAVuBCBk3p_8DgsUeffoTCkkiBojdQOybZk', aba: 'Parâmetros', criar: true, sheet_id_novo: 710001,
    cabecalhos: ['Cliente', 'Procedimento', 'Objetivo', 'Tipo de resultado', 'CPR ótimo até', 'CPR bom até', 'CTR muito alto acima de',
      'CTR excelente a partir de', 'CTR bom a partir de', 'CTR atenção a partir de', 'Tipo de CTR', 'Impressões mínimas', 'Alcance mínimo',
      'Frequência inicial até', 'Frequência boa até', 'Resultados mínimos', 'Gasto mínimo sem resultado', 'Ativo'] },
  { doc: '1w0y2bu6_gA3Ye-u0GYYZT56voGixcD1InqKiB5dhzwY', aba: 'Campanhas Pausadas', criar: true, sheet_id_novo: 710002,
    cabecalhos: ['Data', 'Cliente', 'ID da Conta', 'ID Campanha', 'Nome Campanha', 'Status', 'Reativada em', 'Erro'] },
  { doc: '1w0y2bu6_gA3Ye-u0GYYZT56voGixcD1InqKiB5dhzwY', aba: 'Pausas CPR', criar: true, sheet_id_novo: 710003,
    cabecalhos: ['Data', 'Cliente', 'ID da Conta', 'ID Campanha', 'Nome Campanha', 'Motivo', 'Anúncios'] },
  { doc: '1AR75HoQXFCE7ancGQTLjekHP2eCDt1_-GjuaVgP0iKc', aba: '', renomear: { sheetId: 0, titulo: 'IDS GRUPOS - CLIENTES KONEXT' }, cabecalhos: [] },
];
const sd = $getWorkflowStaticData('global');
sd.prep = { [String($execution.id)]: [] };
return itens.map(j => ({ json: j }));

// ===== utilitários padrão Konext (iguais em todos os fluxos) =====
const n_ = s => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]/g, '');
const pick = (row, nomes) => {
  const m = {};
  for (const k of Object.keys(row || {})) m[n_(k)] = row[k];
  for (const nome of nomes) { const v = m[n_(nome)]; if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim(); }
  return '';
};
const dig = v => String(v ?? '').replace(/\D/g, '');
const sim = (v, padrao) => { const t = n_(v); if (!t) return padrao; return ['sim', 's', 'yes', 'y', 'true', '1', 'ativo'].includes(t); };
const nao = v => ['nao', 'n', 'no', 'false', '0', 'inativo'].includes(n_(v));
const money = v => {
  let s = String(v ?? '').replace(/[^\d,.\-]/g, '');
  if (!s) return null;
  const c = s.lastIndexOf(','), p = s.lastIndexOf('.');
  if (c > -1 && p > -1) s = c > p ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, '');
  else if (c > -1) s = s.replace(',', '.');
  else if (/^\d{1,3}(\.\d{3})+$/.test(s)) s = s.replace(/\./g, '');
  const n = parseFloat(s); return isNaN(n) ? null : n;
};
// Número de WhatsApp ou ID de grupo -> formato aceito pela Evolution API
const jid = v => {
  const s = String(v ?? '').trim();
  if (!s) return '';
  if (/@g\.us$/i.test(s)) return s.replace(/\s/g, '');
  const d = s.replace(/\D/g, '');
  if (!d) return '';
  if (d.startsWith('120363') && d.length >= 15) return d + '@g.us';
  return d.length <= 11 ? '55' + d : d;
};

const it = $('Loop Estrutura').first().json;
const props = $('Propriedades da Planilha').first().json || {};
const errTxt = e => { if (e && typeof e === 'object') e = e.message || JSON.stringify(e); return String(e ?? '').slice(0, 200); };
const rotulo = it.aba ? `"${it.aba}"` : 'planilha de grupos';
if (props.error || !Array.isArray(props.sheets)) return [{ json: { reqs: [], feito: [], erro: `${rotulo}: sem acesso à planilha (${errTxt(props.error)})` } }];
const sheets = props.sheets.map(s => s.properties || {});
const reqs = [], feito = [];
if (it.renomear) {
  const s = sheets.find(x => x.sheetId === it.renomear.sheetId);
  if (s && s.title !== it.renomear.titulo) {
    reqs.push({ updateSheetProperties: { properties: { sheetId: s.sheetId, title: it.renomear.titulo }, fields: 'title' } });
    feito.push(`aba "${s.title}" renomeada para "${it.renomear.titulo}"`);
  }
  return [{ json: { reqs, feito, erro: '' } }];
}
const s = sheets.find(x => n_(x.title) === n_(it.aba));
let sheetId, existentes = [], cols = 26;
if (!s) {
  if (!it.criar) return [{ json: { reqs: [], feito: [], erro: `aba ${rotulo} não encontrada` } }];
  sheetId = it.sheet_id_novo;
  cols = Math.max(26, it.cabecalhos.length);
  reqs.push({ addSheet: { properties: { sheetId, title: it.aba, gridProperties: { rowCount: 1000, columnCount: cols, frozenRowCount: 1 } } } });
  feito.push(`aba ${rotulo} criada`);
} else {
  sheetId = s.sheetId;
  cols = (s.gridProperties || {}).columnCount || 26;
  const h = $('Ler Cabeçalho').first().json || {};
  existentes = (Array.isArray(h.values) && h.values[0]) || [];
}
const faltam = it.cabecalhos.filter(c => !existentes.some(e => n_(e) === n_(c)));
if (faltam.length) {
  const ini = existentes.length;                       // logo depois da última coluna com título
  if (s && ini + faltam.length > cols) reqs.push({ appendDimension: { sheetId, dimension: 'COLUMNS', length: ini + faltam.length - cols } });
  reqs.push({ updateCells: { start: { sheetId, rowIndex: 0, columnIndex: ini },
    rows: [{ values: faltam.map(c => ({ userEnteredValue: { stringValue: c }, userEnteredFormat: { textFormat: { bold: true } } })) }],
    fields: 'userEnteredValue,userEnteredFormat.textFormat.bold' } });
  if (s) feito.push(`colunas adicionadas em ${rotulo}: ${faltam.join(', ')}`);
}
return [{ json: { reqs, feito, erro: '' } }];

const m = $('Montar Alterações').first().json;
const r = $input.first().json || {};
const sd = $getWorkflowStaticData('global'); const ek = String($execution.id);
sd.prep = sd.prep || {}; sd.prep[ek] = sd.prep[ek] || [];
const aplicou = m.reqs.length > 0;
if (m.erro) sd.prep[ek].push('⚠️ ' + m.erro);
else if (aplicou && r.error) sd.prep[ek].push('⚠️ falhou: ' + m.feito.join('; ') + ' — ' + String(r.error.message || JSON.stringify(r.error)).slice(0, 200));
else for (const f of m.feito) sd.prep[ek].push('✅ ' + f);
return [{ json: { ok: true } }];

const sd = $getWorkflowStaticData('global'); const ek = String($execution.id);
const lista = (sd.prep || {})[ek] || [];
if (sd.prep) delete sd.prep[ek];
return [{ json: { mensagem: lista.length ? `🧱 *Planilhas Konext preparadas*\n\n${lista.join('\n')}` : '', mudou: lista.length > 0 } }];
